import{_ as o,o as t,c as i,ae as a}from"./chunks/framework.vXWZTEWX.js";const g=JSON.parse('{"title":"ADR 040: Google OAuth PKCE Migration","description":"","frontmatter":{},"headers":[],"relativePath":"adr/040-google-oauth-pkce.md","filePath":"adr/040-google-oauth-pkce.md"}'),n={name:"adr/040-google-oauth-pkce.md"};function r(s,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-040-google-oauth-pkce-migration" tabindex="-1">ADR 040: Google OAuth PKCE Migration <a class="header-anchor" href="#adr-040-google-oauth-pkce-migration" aria-label="Permalink to &quot;ADR 040: Google OAuth PKCE Migration&quot;">​</a></h1><ul><li>Status: accepted</li><li>Deciders: Elena (Lead Developer), Antigravity (AI Assistant)</li><li>Date: 2026-06-12</li></ul><h2 id="context-and-problem-statement" tabindex="-1">Context and Problem Statement <a class="header-anchor" href="#context-and-problem-statement" aria-label="Permalink to &quot;Context and Problem Statement&quot;">​</a></h2><p>Google OAuth was integrated using the <strong>Implicit Grant</strong> flow (<code>response_type=token</code>), which returns the access token in the URL fragment (<code>#access_token=...</code>). While functional, this exposes the token in the browser&#39;s address bar, creating a security concern:</p><ul><li>The token remains visible in browser history</li><li>Browser extensions with URL access could intercept it</li><li>The implicit flow is deprecated by OAuth 2.1 Security Best Current Practice (BCP 195)</li><li>The Implicit Grant does not support refresh tokens, limiting session longevity</li></ul><p>The application already uses JWT tokens for its own auth — the Google access token was only used for the initial sign-in, not for subsequent API calls. However, its exposure in the URL was an unnecessary attack surface.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li><strong>Security</strong>: Eliminate access token exposure in the browser URL.</li><li><strong>Best Practices</strong>: Align with OAuth 2.1 recommendations and PKCE (Proof Key for Code Exchange) standard.</li><li><strong>Backwards Compatibility</strong>: Existing users should not be affected; the old endpoint can coexist during migration.</li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><strong>Option 1: Backend-Only Callback</strong>: The backend handles the entire OAuth dance — frontend redirects to a backend endpoint, backend exchanges the code, returns a JWT. <ul><li><em>Result</em>: Cleanest security (no token in frontend at all), but requires adding a backend redirect route and updating Google Cloud Console with a server-side redirect URI.</li></ul></li><li><strong>Option 2: Frontend PKCE (Chosen)</strong>: Frontend generates a <code>code_verifier</code> + <code>code_challenge</code>, redirects with <code>response_type=code</code> + <code>code_challenge_method=S256</code>, then sends the authorization code and verifier to the backend for exchange. <ul><li><em>Result</em>: Eliminates token from URL (only a short-lived, single-use <code>?code=</code> appears as a query param). No Google Cloud Console config change needed — redirect_uri stays the frontend URL. Matches existing frontend/backend data flow.</li></ul></li></ul><h2 id="decision-outcome" tabindex="-1">Decision Outcome <a class="header-anchor" href="#decision-outcome" aria-label="Permalink to &quot;Decision Outcome&quot;">​</a></h2><p>Chosen option: <strong>Option 2: Frontend PKCE</strong>.</p><p>The frontend handles PKCE challenge generation and the backend performs the server-side code exchange. This eliminates access token exposure while keeping the redirect_uri pointing at the frontend (no Google Cloud Console changes required).</p><h3 id="positive-consequences" tabindex="-1">Positive Consequences <a class="header-anchor" href="#positive-consequences" aria-label="Permalink to &quot;Positive Consequences&quot;">​</a></h3><ul><li><strong>No access token in URL</strong>: Only <code>?code=</code> (short-lived, single-use authorization code) appears briefly as a query param.</li><li><strong>No Google Cloud Console change</strong>: redirect_uri stays the frontend URL.</li><li><strong>Supports refresh tokens</strong>: The Authorization Code flow can return a refresh token, enabling longer sessions.</li><li><strong>OAuth 2.1 compliant</strong>: Aligns with current security best practices.</li></ul><h3 id="negative-consequences" tabindex="-1">Negative Consequences <a class="header-anchor" href="#negative-consequences" aria-label="Permalink to &quot;Negative Consequences&quot;">​</a></h3><ul><li><strong>Authorization code briefly visible</strong>: The <code>?code=</code> param is visible in the URL during callback, but codes are single-use and expire in ~5 minutes.</li><li><strong>Increased complexity</strong>: Requires crypto (SHA-256) for challenge generation, sessionStorage for state + verifier, and a new backend endpoint for code exchange.</li><li><strong>Server-side exchange required</strong>: Backend needs <code>GOOGLE_CLIENT_SECRET</code> (set via environment variable in Render dashboard).</li></ul><h2 id="implementation-details" tabindex="-1">Implementation Details <a class="header-anchor" href="#implementation-details" aria-label="Permalink to &quot;Implementation Details&quot;">​</a></h2><ul><li><code>GoogleLoginButton.tsx</code>: Generates PKCE <code>code_verifier</code> (crypto.getRandomValues, 32 bytes, base64url) and <code>code_challenge</code> (SHA-256 via crypto.subtle). Stores verifier in sessionStorage. Includes <code>state</code> parameter (random 16 bytes, base64url) for CSRF protection.</li><li><code>AuthContext.tsx</code>: Reads <code>?code</code> from URL query params on callback, verifies <code>state</code> matches sessionStorage, calls <code>POST /api/auth/google/callback</code> with code + verifier. Cleans up state and verifier from sessionStorage after success/failure.</li><li><code>auth.service.ts</code>: Added <code>googleCallback(code, codeVerifier)</code>; removed <code>loginWithGoogle</code>.</li><li><code>AuthService.ts</code> (backend): Added <code>loginWithGoogleCode()</code> — exchanges authorization code at <code>https://oauth2.googleapis.com/token</code>, validates the returned ID token (JWT from Google), finds or creates the user, returns app JWT.</li><li><code>AuthController.ts</code>: Added <code>googleCallback</code> handler with Zod validation.</li><li><code>AuthRoutes.ts</code>: Added <code>POST /api/auth/google/callback</code>.</li><li>Old endpoint <code>POST /api/auth/google</code> (implicit flow) kept for backwards compatibility during migration.</li></ul><h2 id="supersedes" tabindex="-1">Supersedes <a class="header-anchor" href="#supersedes" aria-label="Permalink to &quot;Supersedes&quot;">​</a></h2><p>This ADR supersedes the implicit grant implementation described in <a href="./018-auth-strategy-pivot.html">ADR 018</a>. The core decision (redirect over popup) remains valid; only the OAuth flow itself is upgraded from Implicit Grant to Authorization Code + PKCE.</p>',21)])])}const p=o(n,[["render",r]]);export{g as __pageData,p as default};
